Schema:
{
  "additionalProperties": false,
  "description": "This is the format describing the game state for the PlanetWars game, used in the development off MOZAIC",
  "properties": {
    "expeditions": {
      "description": "List of all expeditions in this game. These are the ships on the way to another planet",
      "items": {
        "additionalProperties": false,
        "description": "a command",
        "properties": {
          "destination": {
            "type": "string"
          },
          "id": {
            "type": "integer"
          },
          "origin": {
            "type": "string"
          },
          "owner": {
            "type": "string"
          },
          "ship_count": {
            "minimum": 0,
            "type": "integer"
          },
          "turns_remaining": {
            "minimum": 0,
            "type": "integer"
          }
        },
        "type": "object"
      },
      "type": "array"
    },
    "planets": {
      "description": "List of all planets in the game",
      "items": {
        "additionalProperties": false,
        "description": "planet",
        "properties": {
          "name": {
            "type": "string"
          },
          "owner": {
            "type": "string"
          },
          "ship_count": {
            "minimum": 0,
            "type": "integer"
          },
          "x": {
            "type": "integer"
          },
          "y": {
            "type": "integer"
          }
        },
        "type": "object"
      },
      "type": "array"
    },
    "players": {
      "description": "List of all players in the game",
      "items": {
        "type": "string"
      },
      "minItems": 2,
      "type": "array",
      "_uniqueItems": true
    }
  },
  "required": [
    "players",
    "planets",
    "expeditions"
  ],
  "title": "PlanetWars"
}

